/** Fachada pública de MAPLI: mismos 11 puntos de entrada que exportaba L035. */
@Service
@RequiredArgsConstructor
public class MapliFachada implements MapliApi {

    static final int LIBRERIA_NO_DISPONIBLE = 99;

    private final ObjectProvider<MapliApi> implementacion;   // MAPLICALL = S500_L036 (MapliService)
    private final AtomicBoolean ligaActiva = new AtomicBoolean(false);   // B_LLAMAL036, global (SHAREDBYALL)

    /** S038L035_01_PROG_INI. Los envoltorios 02, 03, 04, 05, 30, 31, 32, 33 y 34 tienen la misma forma. */
    @Override
    public ResultadoMapli inicioPrograma(LlavePrograma llave, InicioPrograma in, Consumer<Integer> idSalida) {
        return delega(api -> api.inicioPrograma(llave, in, idSalida));
    }

    private ResultadoMapli delega(Function<MapliApi, ResultadoMapli> llamada) {
        if (!ligaActiva.get()) {
            return ResultadoMapli.LIBRERIA_NO_DISPONIBLE;   // 99: el programa de negocio sigue corriendo
        }
        return llamada.apply(implementacion.getObject());
    }
}

/** S038L035_06_NUM_REGS: único envoltorio con lógica propia. */
public ResultadoConteo numeroRegistros(byte[] entrada) {
    if (!ligaActiva.get()) return ResultadoConteo.error(LIBRERIA_NO_DISPONIBLE);
    String estructura = Ebcdic.texto(entrada, 0, 17);
    String tituloBase = Ebcdic.texto(entrada, 17, 56).stripTrailing();   // L036 busca el fin en un blanco
    var r = implementacion.getObject().cuentaPoblacion(estructura, tituloBase);
    if (r.codigoInterno() > 0) {
        return ResultadoConteo.error(r.codigoInterno() + OFFSET_ERRORES_ESTRUCTURA);   // 71..76
    }
    return ResultadoConteo.ok(r.poblacion());   // long tipado; el adaptador COBOL decide el formato
}

/** p. ej. 1 -> 71 NO SE ENCONTRO EL ARCHIVO DE CONTROL DE LA BASE ... 6 -> 76 ESTRUCTURA DESCONOCIDA. */
static final int OFFSET_ERRORES_ESTRUCTURA = 70;

public record ResultadoConteo(int codigo, long poblacion) {
    static ResultadoConteo ok(long p)      { return new ResultadoConteo(0, p); }
    static ResultadoConteo error(int c)    { return new ResultadoConteo(c, 0); }
}

/** S038L035_34_NUMDECSI: número de CSI (2) y nombre (20) del equipo donde corre MAPLI. */
public ResultadoMapli numeroDeCsi(Consumer<IdentificacionCsi> salida) {
    return delega(api -> {
        ResultadoMapli r = api.numeroDeCsi(salida);
        return r == null ? ResultadoMapli.OK : r;   // L036 no asigna su resultado: se fija 0 explícito
    });
}

public record IdentificacionCsi(int numero, String nombre) {}

@Component
@RequiredArgsConstructor
class ResolutorVersionL036 {

    private final CtlVerClient ctlver;           // LIBACCESS = BYFUNCTION, FUNCTIONNAME = "CTLVERS"
    private final MapliProperties props;          // mapli.id-implementacion: "S500L036"

    /** PROC_DAME_TIT_S038L036: la versión de la implementación se resuelve en ejecución. */
    Optional<String> versionVigente() {
        Optional<String> titulo = ctlver.titulo(props.idImplementacion());
        if (titulo.isEmpty()) {
            log.error("150721-03-S500-L035-25MTP002 ERROR CALL CTLVER");   // DF_DISPLAY
            // Comportamiento original: no desactiva la liga ni aborta; se conserva la versión previa.
        }
        return titulo;
    }
}

// En MapliFachada
private final ResolutorVersionL036 resolutor;

/** PROC_LEVANTA: marca la liga activa, resuelve versión y fuerza la carga de L036. */
@PostConstruct
void levantaLiga() {
    ligaActiva.set(true);
    resolutor.versionVigente();
    implementacion.getObject();   // S038L035_99_LEVANTA_C: instancia MapliService y su @PostConstruct
                                   // (apertura de S500BD05MAPLI y recarga del registro)
}
// FREEZE(CONTROL, PROC_CONTROL): el singleton queda residente y el control del operador
// se publica como endpoint (ver ControlMapliEndpoint).

@Component
@Endpoint(id = "mapli")
@RequiredArgsConstructor
public class ControlMapliEndpoint {

    private final MapliFachada fachada;

    /** TASKVALUE 1, 2, 3 y 4 de PROC_CONTROL con los mismos textos de consola. */
    @WriteOperation
    public String comando(int taskValue) {
        return switch (taskValue) {
            case 1 -> { fachada.suspende(); yield "SE SUSPENDE LIGA A L036"; }   // DELINKLIBRARY
            case 2 -> { fachada.levantaLiga(); yield "SE HACE LIGA A L036"; }
            case 3 -> fachada.ligaActiva() ? "STATUS ACCESO A L036: CON" : "STATUS ACCESO A L036: SIN";
            case 4 -> { fachada.suspende(); yield "MAPLI RETIRADA"; }            // en MCP: sin mensaje
            default -> "SIN ACCION";
        };
    }

    @ReadOperation
    public Map<String, Object> estado() { return Map.of("ligaActiva", fachada.ligaActiva()); }
}
